function tileCenter(tile: TileCoordinate, footprint = 1): Vector3 {
  const half = WORLD_SIZE / 2;
  return new Vector3(
    -half + (tile.x + footprint / 2) * TILE_SIZE,
    0,
    -half + (tile.y + footprint / 2) * TILE_SIZE,
