      const step = orthogonalNeighbors(citizen)
        .filter((tile) => roadKeys.has(tileKey(tile)))
        .sort((left, right) => tileKey(left) - tileKey(right))[0];
      if (step) {
        citizen.x = step.x;
        citizen.y = step.y;
      }
    }
  }
  world.citizens.sort((left, right) => left.id - right.id);
