function cloneBuilding(building: BuildingView): BuildingView {
  if (isHouse(building)) {
    return {
      ...building,
      footprint: { width: HOUSE_FOOTPRINT, height: HOUSE_FOOTPRINT },
    };
  }
  if (isFarm(building)) {
    return {
      ...building,
      cropType: building.cropType ?? "millet",
      footprint: { width: FARM_FOOTPRINT, height: FARM_FOOTPRINT },
