        "+    households: [],",
        "+    migrants: [],",
        "+    performers: [],",
        "+    citizens: [],",
        "+    laborPolicy: {",
        "+      ...DEFAULT_LABOR_POLICY,",
        "+      priorities: [...DEFAULT_LABOR_POLICY.priorities],",
        "+    },",
        "+    shennongFavor: 0,",
        "+    diplomacy: { relation: 0, tradeOpen: false, envoys: [] },",
        "+    economy: {",
        "+      treasury: 500,",
