        "+function reconcileDiplomacy(world: WorldState): void {",
        "+  const arrived = world.diplomacy.envoys.filter(",
        "+    (envoy) => envoy.arrivesAtTick <= world.tick,",
        "+  );",
        "+  if (arrived.length === 0) return;",
