        "+    (envoy) => envoy.arrivesAtTick > world.tick,",
        "+  );",
        "+  world.diplomacy.relation = Math.min(",
        "+    100,",
        "+    world.diplomacy.relation + arrived.length * 25,",
        "+  );",
        "+  if (world.diplomacy.relation >= 50) world.diplomacy.tradeOpen = true;",
