        "+              distance: shortestRoadDistance(",
        "+                world,",
        "+                market,",
        "+                house,",
        "+                MARKET_SERVICE_RANGE,",
        "+              ),",
        "+            }",
        "+          : null;",
        "+      })",
        "+      .filter(",
        "+        (",
        "+          candidate,",
