        "+      (office) => shortestRoadDistance(world, office, house, 12) !== null,",
        "+    );",
        "+    return [",
        "+      {",
        "+        houseId: house.id,",
        "+        level: house.level,",
        "+        covered,",
        "+        desirability: desirabilityAtSite(world.buildings, house.x, house.y)",
        "+          .score,",
