        "+",
        "+export function advanceTicks(world: WorldState, count: number): void {",
        "+  if (!Number.isSafeInteger(count) || count < 1) {",
        "+    throw new Error("推进 tick 数必须是正安全整数");",
        "+  }",
        "+  if (!advanceTicksAtomically(world, count)) {",
        "+    throw new Error("模拟计数已耗尽");",
