        "+",
        "+function advanceTicksAtomically(world: WorldState, count: number): boolean {",
        "+  if (!Number.isSafeInteger(count) || count < 1) {",
        "+    throw new Error("推进 tick 数必须是正安全整数");",
        "+  }",
        "+  if (world.tick > Number.MAX_SAFE_INTEGER - count) return false;",
