        "+      (border) => border.x === tile.x && border.y === tile.y,",
        "+    );",
        "+    if (!passed) continue;",
        "+    const household = households.get(house.id);",
        "+    if (household) {",
        "+      household.entertainmentReserveTicks = HOUSEHOLD_FOOD_RESERVE_MAX;",
        "+    }",
        "+  }",
